// Node's own resolution rule sends this require to vt2-boot-lib's OWN
// node_modules, not the top-level one: a package's private tree is
// searched before its parents'. The two installs are identical in name,
// version and vulnerable export name, and distinguishable only by path.
const dep = require("vt2-vuln-lib");

// A private helper that exists only to share the vulnerable export's
// spelling (RWF-011). Nothing publishes it, nothing calls it, and it is
// declared BEFORE everything real -- so both a same-file bare-name search
// and a "first function in the file" heuristic land here.
function dangerousOp(input) {
  return "decoy:" + input;
}

// The branch that reaches the vulnerable package. Nothing in this file
// calls it: the ONLY way it ever runs is by being this module's exported
// value.
function fastPath(input) {
  return dep.dangerousOp(input);
}

// The branch that does not.
function slowPath(input) {
  return "slow:" + input;
}

class Base {}

// ===========================================================================
// THE FACTORY THE WHOLE CASE TURNS ON.
//
// Two endings. NEITHER of them lets `class Mode extends heritage(FLAG) {}`
// finish, and they fail it for two DIFFERENT reasons:
//
//   flag truthy -- the heritage expression completes ABRUPTLY, so
//                  ClassDefinitionEvaluation is never entered at all;
//   flag falsy  -- the heritage expression completes NORMALLY with `1`,
//                  and ClassDefinitionEvaluation then throws
//                  `TypeError: Class extends value 1 is not a constructor
//                  or null` on its own heritage validation.
//
// Read either ending alone and there is nothing to fire on. `heritage` is
// not always-throwing, so a "this call cannot complete normally" rule
// refuses it -- correctly, and the plain call below proves why. It has no
// single unconditional return, so a "what value does this call produce"
// rule is unknown. The class-definition failure is a property of the path
// SET, and of nothing smaller.
// ===========================================================================
function heritage(flag) {
  if (flag) {
    throw new Error("fast mode is not supported by this build");
  }
  return 1;
}

// A conditional guard the analyzer cannot evaluate.
const FLAG = process.env.VT2_CONDITION === "yes";

// ===========================================================================
// THE PLAIN-CALL CONTROL, and the sharpest one in the file.
//
// The SAME callable, at module scope, on every load, in a position that is
// unquestionably evaluated. It returns `1` and module evaluation continues
// straight past it. An analyzer that concluded "`heritage` is fatal" rather
// than "this CLASS HERITAGE is fatal" would cut the module off HERE, before
// either export is written -- right by accident about nothing, and wrong
// about every module that calls a conditionally-throwing helper.
// ===========================================================================
const plainCallResult = heritage(false);

if (process.env.VT2_MODE === "fast") {
  module.exports = fastPath;
  // ==================================================================
  // THE CUTOFF. This is the entire case.
  //
  // Whichever way `FLAG` goes, this class definition does not complete:
  // one path throws before the class is entered, the other reaches
  // heritage validation with `1`. `Mode` is never bound, and module
  // evaluation on this branch ends here -- so the assignment below is
  // NOT reached on this load, and `module.exports` IS `fastPath`.
  // ==================================================================
  class Mode extends heritage(FLAG) {}

  void Mode;
}

// ===========================================================================
// THE VALID-PATH NEGATIVE CONTROLS. Every factory below ALSO has more than
// one ending -- so every one of them reaches the same multi-path summary --
// and every one of them keeps at least one ending that leaves the class
// definition able to complete. All seven classes really are bound, on every
// load that gets here.
//
// Where the protection against over-firing on them actually lives, stated
// accurately. It is NOT this case's end-to-end verdict. The canonical
// heritage cutoff above -- `class Mode extends heritage(FLAG)`, inside the
// `fast` branch -- already makes this module's exported value ambiguous, so
// this case is UNKNOWN before any of the factories below is even reached.
// A second cutoff cannot move an already-ambiguous export, and mutating one
// of these factories to be all-fatal leaves ADV2-087 UNKNOWN and passing.
// Independently verified by mutation.
//
// So these seven are real controls, but they are enforced at the SEMANTIC
// (module-model) layer, by the path-summary matrix in
// src/code-intelligence/module-model.multipath-class-definition-completion.test.ts,
// which asserts each shape refuses a cutoff on its own. They are kept here
// because a heritage factory with several endings, all but one fatal, is
// exactly what this family looks like in real source, and because they
// document the boundary beside the defect it bounds -- not because this
// file's verdict discriminates them.
// ===========================================================================

// throw + CONSTRUCTABLE. One throwing branch must never be promoted to an
// all-path conclusion (the P0-B boundary).
function throwOrBase(flag) {
  if (flag) {
    throw new Error("boom");
  }
  return Base;
}

// invalid + CONSTRUCTABLE.
function invalidOrBase(flag) {
  if (flag) {
    return 1;
  }
  return Base;
}

// invalid + VALID NULL. `class C extends null {}` is LEGAL. Folding `null`
// in with the non-constructable values is the single worst available
// mistake here, so it is a control in its own right.
function invalidOrNull(flag) {
  if (flag) {
    return 1;
  }
  return null;
}

// throw + valid null.
function throwOrNull(flag) {
  if (flag) {
    throw new Error("boom");
  }
  return null;
}

// invalid + UNKNOWN. One unclassifiable ending must refuse the whole
// summary: unsupported semantics degrade to unknown, never to false
// certainty.
function invalidOrUnknown(flag) {
  if (flag) {
    return 1;
  }
  return dep.dangerousOp;
}

// A nested `if` whose VALID leaf is two levels down. If the descent lost
// that leaf, this module would be cut off and the loss would be silent.
function nestedWithValidLeaf(a, b) {
  if (a) {
    if (b) return Base;
    throw new Error("boom");
  }
  return 2;
}

// Unmodeled control flow, which must poison the summary outright rather
// than be reasoned about. Deliberately ALSO completable at runtime, so this
// file's two-worlds shape survives.
function loopBodied(flag) {
  while (flag) {
    return Base;
  }
  return 2;
}

class FromThrowOrBase extends throwOrBase(false) {}
class FromInvalidOrBase extends invalidOrBase(false) {}
class FromInvalidOrNull extends invalidOrNull(false) {}
class FromThrowOrNull extends throwOrNull(false) {}
class FromInvalidOrUnknown extends invalidOrUnknown(false) {}
class FromNestedValid extends nestedWithValidLeaf(true, true) {}
class FromLoop extends loopBodied(true) {}

// ===========================================================================
// THE DEFERRED AND UNRESOLVED-CALLEE CONTROLS. Each of these WOULD be a
// genuine cutoff if it were evaluated at module scope with a callee this
// analyzer resolves. None of them is.
// ===========================================================================

// A class whose heritage really is fatal on every path -- inside a function
// nothing calls at module scope. Writing a function evaluates nothing, so
// there is no module-time cutoff here.
function configure() {
  class Deferred extends heritage(false) {}
  return Deferred;
}

// The ALIAS and MEMBER forms of the same fatal factory. Both really would
// abort under real `node`, and both are refused here because the callee is
// not an exact local callable -- the P0-E / RWF-028 boundary, open,
// recorded, and not to be closed from a class-heritage rule. They are
// written inside a never-called function because hoisting them to module
// scope would make this module throw on EVERY load and destroy the
// two-worlds shape the case depends on.
const aliasHeritage = heritage;
const holder = { heritage };
function probeIndirect() {
  class ViaAlias extends aliasHeritage(false) {}
  class ViaMember extends holder.heritage(false) {}
  return [ViaAlias, ViaMember];
}

// A GENUINELY REASSIGNED callee. `reassigned`'s declaration says every
// ending is fatal, and that summary is STALE -- the assignment below
// replaces it with a factory that returns a perfectly good class, and the
// class on the next line really is bound. Trusting the declaration would
// withdraw authority from an export that is genuinely reached (RWF-025).
function reassigned(flag) {
  if (flag) return 1;
  return 2;
}
reassigned = () => Base;
class FromReassigned extends reassigned(false) {}

// Reached on every OTHER load, and on no load where the branch above was
// taken.
module.exports = slowPath;

void dangerousOp;
void plainCallResult;
void FromThrowOrBase;
void FromInvalidOrBase;
void FromInvalidOrNull;
void FromThrowOrNull;
void FromInvalidOrUnknown;
void FromNestedValid;
void FromLoop;
void FromReassigned;
void configure;
void probeIndirect;
